import { notFound } from 'next/navigation';
import { tools, defaultToolIds, getIcon } from '@/lib/tools-data';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { ForgePanel } from '@/components/forge/panel';
import { AddTabDialog } from '@/components/forge/add-tab-dialog';
import { DeleteTabDialog } from '@/components/forge/delete-tab-dialog';
import { AddPanelDialog } from '@/components/forge/add-panel-dialog';

export default async function ToolPage({ params }: { params: { toolId: string } }) {
  const tool = tools.find((t) => t.id === params.toolId);

  if (!tool) {
    notFound();
  }

  const isDefaultTool = defaultToolIds.includes(tool.id);

  return (
    <div className="space-y-6">
      <header>
        <h1 className="text-4xl font-bold font-headline tracking-tight">
          {tool.name}
        </h1>
      </header>

      <Tabs defaultValue={tool.layout[0]?.id} className="w-full">
        <div className="flex items-center gap-2">
          <TabsList>
            {tool.layout.map((tab) => {
                const TabIcon = getIcon(tab.icon);
                return (
                    <div key={tab.id} className="relative group/tab">
                        <TabsTrigger value={tab.id}>
                            <TabIcon className="mr-2 h-4 w-4"/>
                            {tab.name}
                        </TabsTrigger>
                        {!isDefaultTool && (
                        <DeleteTabDialog toolId={tool.id} tabId={tab.id} tabName={tab.name}>
                            <button className="absolute -top-1 -right-1 z-10 hidden h-4 w-4 items-center justify-center rounded-full bg-destructive text-destructive-foreground opacity-80 transition-opacity hover:opacity-100 group-hover/tab:flex">
                            &times;
                            </button>
                        </DeleteTabDialog>
                        )}
                    </div>
                )
            })}
          </TabsList>
          {!isDefaultTool && <AddTabDialog toolId={tool.id} />}
        </div>

        {tool.layout.map((tab) => (
          <TabsContent key={tab.id} value={tab.id}>
             <div className="mb-4 flex items-center justify-end">
              {!isDefaultTool && <AddPanelDialog toolId={tool.id} tabId={tab.id} />}
            </div>
            <div className="grid grid-cols-1 gap-6 lg:grid-cols-2 xl:grid-cols-3">
              {tab.panels.map((panel) => (
                <ForgePanel
                  key={panel.id}
                  panel={panel}
                  toolId={tool.id}
                  tabId={tab.id}
                  toolType={tool.name}
                />
              ))}
            </div>
          </TabsContent>
        ))}
      </Tabs>
    </div>
  );
}

